package com.bank.buildbuy;

import com.bank.buildbuy.model.Capability;
import com.bank.buildbuy.service.BuildBuyAdvisor;
import java.util.logging.*;

// Runnable demo: decide build vs buy for a retry library and a proprietary fraud rule.
public class BuildBuyDemo {
    private static final Logger log = Logger.getLogger("BuildBuy");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        BuildBuyAdvisor advisor = new BuildBuyAdvisor(log);

        // Retry logic: commodity, high existing fit, not differentiating → BUY/reuse.
        advisor.advise(new Capability(
            "Retry with backoff for payment calls",
            95,     // existing-solution fit %
            false,  // not a differentiator
            false,  // security-sensitive? not specifically
            8));    // build maintenance burden (high)

        // Fraud scoring: unique to the bank, no off-the-shelf fit, core IP → BUILD.
        advisor.advise(new Capability(
            "Proprietary fraud-scoring rules",
            20,     // existing-solution fit % (low — unique)
            true,   // core differentiator / competitive edge
            false,
            6));
    }
}
