package com.bank.buildbuy.model;

// Describes a capability to decide build vs buy.
public class Capability {
    private final String name;
    private final int existingFitPercent;   // how well an existing solution fits
    private final boolean coreDifferentiator; // is it a competitive edge?
    private final boolean securitySensitive;  // e.g. crypto → never roll your own
    private final int buildMaintenanceBurden; // 1-10, higher = more costly to maintain

    public Capability(String name, int existingFitPercent, boolean coreDifferentiator,
                      boolean securitySensitive, int buildMaintenanceBurden) {
        this.name = name;
        this.existingFitPercent = existingFitPercent;
        this.coreDifferentiator = coreDifferentiator;
        this.securitySensitive = securitySensitive;
        this.buildMaintenanceBurden = buildMaintenanceBurden;
    }

    public String getName() { return name; }
    public int getExistingFitPercent() { return existingFitPercent; }
    public boolean isCoreDifferentiator() { return coreDifferentiator; }
    public boolean isSecuritySensitive() { return securitySensitive; }
    public int getBuildMaintenanceBurden() { return buildMaintenanceBurden; }
}
