package com.bank.buildbuy.service;

import com.bank.buildbuy.model.Capability;
import java.util.logging.*;

// Recommends BUY for commodity/high-fit/security-sensitive; BUILD only for core unique needs.
public class BuildBuyAdvisor {
    private final Logger log;

    public BuildBuyAdvisor(Logger log) { this.log = log; }

    public void advise(Capability c) {
        // Rule 1: never roll your own for security-sensitive commodities.
        if (c.isSecuritySensitive()) {
            log.info(() -> "BUY/reuse: \"" + c.getName()
                + "\" is security-sensitive — use a vetted, audited library.");
            return;
        }
        // Rule 2: core differentiator with low existing fit → BUILD.
        if (c.isCoreDifferentiator() && c.getExistingFitPercent() < 50) {
            log.info(() -> "BUILD: \"" + c.getName()
                + "\" is core IP (fit only " + c.getExistingFitPercent()
                + "%) — build in-house for control and differentiation.");
            return;
        }
        // Rule 3: commodity with high existing fit → BUY/reuse (avoid maintenance tail).
        if (c.getExistingFitPercent() >= 80) {
            log.info(() -> "BUY/reuse: \"" + c.getName() + "\" has "
                + c.getExistingFitPercent() + "% fit and high build-maintenance burden ("
                + c.getBuildMaintenanceBurden() + "/10) — reuse a proven solution.");
            return;
        }
        log.warning(() -> "Mixed case for \"" + c.getName()
            + "\" — consider buying commodity parts and building only the unique layer.");
    }
}
